import unittest
from archive_extract import effect_facts


class BloodMageObservations(unittest.TestCase):
    def test_reviewed_source_values_and_unknowns(self):
        cases = {'Infuses 113 health into your defensive target. Heals for an extra 2% per level of Blood Union.': {'effect_reported': 'healing', 'recipient_reported': 'your defensive target', 'health_amount': 113, 'blood_union_bonus_percent_per_level': 2, 'bonus_basis': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, "Grafts blood and flesh onto your defensive target's party, granting them an additional 54 health for 1 hour.": {'effect_reported': 'additional_health', 'recipient_reported': "your defensive target's party", 'health_amount': 54, 'duration_seconds': 3600, 'health_pool_semantics': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, 'Infuses 321 health into your defensive target. Heals for an extra 2% per level of Blood Union.': {'effect_reported': 'healing', 'recipient_reported': 'your defensive target', 'health_amount': 321, 'blood_union_bonus_percent_per_level': 2, 'bonus_basis': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, 'Transmutes 115 health into 115 energy.': {'effect_reported': 'health_to_energy_conversion', 'health_consumed': 115, 'energy_granted': 115, 'recipient_reported': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, "Fills your defensive target's party with life, granting them 23 additional vitality.": {'effect_reported': 'stat_increase', 'recipient_reported': "your defensive target's party", 'stat_reported': 'vitality', 'amount': 23, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}}
        for literal, expected in cases.items():
            with self.subTest(literal=literal):
                fact, = [f for f in effect_facts(literal) if f['kind'] == 'blood_mage_healing_conversion_buff_observation']
                for key, value in expected.items():
                    self.assertEqual(fact[key], value)
                self.assertTrue(fact['conditions_unparsed'])

    def test_changed_numbers_or_conditions_are_not_promoted(self):
        for literal in {'Infuses 113 health into your defensive target. Heals for an extra 2% per level of Blood Union.': {'effect_reported': 'healing', 'recipient_reported': 'your defensive target', 'health_amount': 113, 'blood_union_bonus_percent_per_level': 2, 'bonus_basis': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, "Grafts blood and flesh onto your defensive target's party, granting them an additional 54 health for 1 hour.": {'effect_reported': 'additional_health', 'recipient_reported': "your defensive target's party", 'health_amount': 54, 'duration_seconds': 3600, 'health_pool_semantics': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, 'Infuses 321 health into your defensive target. Heals for an extra 2% per level of Blood Union.': {'effect_reported': 'healing', 'recipient_reported': 'your defensive target', 'health_amount': 321, 'blood_union_bonus_percent_per_level': 2, 'bonus_basis': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, 'Transmutes 115 health into 115 energy.': {'effect_reported': 'health_to_energy_conversion', 'health_consumed': 115, 'energy_granted': 115, 'recipient_reported': None, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}, "Fills your defensive target's party with life, granting them 23 additional vitality.": {'effect_reported': 'stat_increase', 'recipient_reported': "your defensive target's party", 'stat_reported': 'vitality', 'amount': 23, 'duration_seconds': None, 'tick_interval_seconds': None, 'stacking_rules': None, 'operative_values': None, 'historical_authentication': None}}:
            for altered in (literal + ' Only while resting.', literal.replace('health', 'damage'), literal.replace('23', '24').replace('113', '114').replace('321', '322').replace('115', '116').replace('54', '55')):
                if altered == literal: continue
                self.assertFalse(any(f['kind'] == 'blood_mage_healing_conversion_buff_observation' for f in effect_facts(altered)))
